1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Console\Commands;
6	
7	use App\Models\Fabric;
8	use App\Models\FabricCategory;
9	use Illuminate\Console\Command;
10	use Illuminate\Support\Facades\DB;
11	use Illuminate\Support\Str;
12	use OpenSpout\Common\Entity\Cell\FormulaCell;
13	use OpenSpout\Reader\XLSX\Reader;
14	
15	/**
16	 * Import dei singoli colori tessuto/pelle (`Fabric`) dal listino CAPITAL
17	 * `CAPITAL Tessuti Pelli Uniti 2026 .xlsx`, sotto le rispettive `FabricCategory` (tipologie).
18	 *
19	 * Il file elenca 12 tipologie: 8 mappano sulle tipologie del catalogo, 4 sono
20	 * varianti presenti solo qui (3 trapuntate + grana Da Vinci) e hanno una
21	 * FabricCategory dedicata (senza prodotti associati). Le tipologie
22	 * "Nabuk treccia" e "Luxury & Exclusive" non hanno colori in questo listino.
23	 *
24	 * Nome colore = colonna D (Codice) + colonna E (Colore). Slug = categoria +
25	 * colonna P (CODICE) quando presente, altrimenti derivato dal nome (garantisce
26	 * unicità globale: P non è unico tra soft-grain e Da Vinci, il nome non è unico
27	 * tra sintetica e sintetica TRAP).
28	 *
29	 * Oltre a nome/slug vengono importati i campi anagrafici/commerciali: codice,
30	 * colore, categoria prezzo (Cat.), campionario, euro m/taglio, nota,
31	 * CATEGORIA, CODICE (sku) e DESCRIZIONE (formula, letta come valore calcolato).
32	 * ART (col. N) è costante per tipologia e viene scritto sulla FabricCategory.
33	 *
34	 * Prerequisito: MaterialFabricSeeder (tassonomia FabricCategory). Idempotente.
35	 */
36	class ImportIndoorTessuti extends Command
37	{
38	    protected $signature = 'app:import-fabrics '
39	        . '{--file=storage/app/private/import/indoor/CAPITAL Tessuti Pelli Uniti 2026 .xlsx} '
40	        . '{--fresh : Svuota le fabrics delle tipologie interessate prima di reimportare}';
41	
42	    protected $description = 'Import dei colori tessuto/pelle (Fabric) dal listino CAPITAL';
43	
44	    /** Indici colonna (0-based) nel listino CAPITAL. */
45	    private const COL = [
46	        'tipologia' => 0,      // A
47	        'codice' => 3,         // D
48	        'colore' => 4,         // E
49	        'cat' => 5,            // F (Cat. = categoria prezzo)
50	        'campionario' => 7,    // H
51	        'euro' => 11,          // L (euro m/taglio)
52	        'nota1' => 12,         // M
53	        'art' => 13,           // N (ART)
54	        'categoria' => 14,     // O (CATEGORIA)
55	        'sku' => 15,           // P (CODICE)
56	        'descrizione' => 16,   // Q (DESCRIZIONE, formula)
57	    ];
58	
59	    /**
60	     * Tipologia CAPITAL (chiave normalizzata: lowercase, trim, spazi collassati)
61	     * → slug FabricCategory di destinazione.
62	     *
63	     * @var array<string, string>
64	     */
65	    private const TIPOLOGIA_MAP = [
66	        'bouclè bi-elastico' => 'boucle-fabric',
67	        'ciniglia' => 'lord-fabric',
68	        'tessuto unito' => 'york-fabric',
69	        'velluto unito' => 'velvet',
70	        'velluto trapuntato' => 'velluto-trapuntato',
71	        'pelle sintetica' => 'synthetic-leather',
72	        'pelle sintetica trap' => 'pelle-sintetica-trap',
73	        'pelle camosciata' => 'vintage-leather',
74	        'pelle grana vellutata' => 'soft-grain-leather',
75	        'pelle grana da vinci' => 'pelle-grana-da-vinci',
76	        'pelle nabuk' => 'nabuk-leather',
77	        'pelle nabuk trap.' => 'nabuk-trap',
78	    ];
79	
80	    /** @var array<string, FabricCategory> */
81	    private array $categoryCache = [];
82	
83	    /** @var array<string, int> sort progressivo per categoria */
84	    private array $sortCounter = [];
85	
86	    public function handle(): int
87	    {
88	        $file = (string) $this->option('file');
89	        if (! is_file($file)) {
90	            $this->error("File non trovato: {$file}");
91	
92	            return self::FAILURE;
93	        }
94	
95	        $stats = ['rows' => 0, 'imported' => 0, 'skipped' => 0, 'unmapped' => 0];
96	        $unmapped = [];
97	
98	        DB::transaction(function () use ($file, &$stats, &$unmapped): void {
99	            if ($this->option('fresh')) {
100	                $slugs = array_values(array_unique(array_values(self::TIPOLOGIA_MAP)));
101	                $categoryIds = FabricCategory::query()->whereIn('slug', $slugs)->pluck('id');
102	                Fabric::query()->whereIn('fabric_category_id', $categoryIds)->delete();
103	            }
104	
105	            $header = true;
106	            $reader = new Reader();
107	            $reader->open($file);
108	            foreach ($reader->getSheetIterator() as $sheet) {
109	                foreach ($sheet->getRowIterator() as $row) {
110	                    if ($header) {
111	                        $header = false;
112	
113	                        continue;
114	                    }
115	
116	                    // le celle formula (es. DESCRIZIONE) espongono il valore calcolato, non la formula
117	                    $cells = array_values(array_map(
118	                        fn ($c): mixed => $c instanceof FormulaCell ? $c->getComputedValue() : $c->getValue(),
119	                        $row->getCells(),
120	                    ));
121	                    $tipologia = $this->s($cells[self::COL['tipologia']] ?? '');
122	                    if ($tipologia === '') {
123	                        continue;
124	                    }
125	                    $stats['rows']++;
126	
127	                    $key = $this->normalize($tipologia);
128	                    $slug = self::TIPOLOGIA_MAP[$key] ?? null;
129	                    if ($slug === null) {
130	                        $stats['unmapped']++;
131	                        $unmapped[$tipologia] = true;
132	
133	                        continue;
134	                    }
135	
136	                    $codice = $this->s($cells[self::COL['codice']] ?? '');
137	                    $colore = $this->s($cells[self::COL['colore']] ?? '');
138	                    $name = trim("{$codice} {$colore}");
139	                    if ($name === '') {
140	                        $stats['skipped']++; // riga senza colore (es. Velluto trapuntato)
141	
142	                        continue;
143	                    }
144	
145	                    $sku = $this->s($cells[self::COL['sku']] ?? '');
146	                    $fabricSlug = $slug . '-' . Str::slug($sku !== '' ? $sku : $name);
147	
148	                    $euro = $cells[self::COL['euro']] ?? null;
149	
150	                    $category = $this->resolveCategory($slug);
151	
152	                    // ART è costante per tipologia: lo scriviamo sulla categoria
153	                    $art = $this->sOrNull($cells[self::COL['art']] ?? null);
154	                    if ($art !== null && $category->art_code !== $art) {
155	                        $category->update(['art_code' => $art]);
156	                    }
157	                    Fabric::query()->updateOrCreate(
158	                        ['slug' => $fabricSlug],
159	                        [
160	                            'fabric_category_id' => $category->id,
161	                            'name' => ['it' => $name, 'en' => $name],
162	                            'sort' => $this->sortCounter[$slug] = ($this->sortCounter[$slug] ?? 0) + 1,
163	                            'code' => $codice !== '' ? $codice : null,
164	                            'color' => $colore !== '' ? $colore : null,
165	                            'price_category' => $this->sOrNull($cells[self::COL['cat']] ?? null),
166	                            'sample_size' => $this->sOrNull($cells[self::COL['campionario']] ?? null),
167	                            'unit_price' => is_numeric($euro) ? (float) $euro : null,
168	                            'note' => $this->sOrNull($cells[self::COL['nota1']] ?? null),
169	                            'category_code' => $this->sOrNull($cells[self::COL['categoria']] ?? null),
170	                            'sku' => $sku !== '' ? $sku : null,
171	                            'description' => $this->sOrNull($cells[self::COL['descrizione']] ?? null),
172	                        ],
173	                    );
174	                    $stats['imported']++;
175	                }
176	
177	                break;
178	            }
179	            $reader->close();
180	        });
181	
182	        if ($unmapped !== []) {
183	            $this->warn('Tipologie non mappate (ignorate): ' . implode(', ', array_keys($unmapped)));
184	        }
185	
186	        $this->info('Import colori tessuto completato.');
187	        $this->table(
188	            ['Metrica', 'Valore'],
189	            collect($stats)->map(fn ($v, $k): array => [$k, $v])->values()->all(),
190	        );
191	
192	        return self::SUCCESS;
193	    }
194	
195	    private function resolveCategory(string $slug): FabricCategory
196	    {
197	        return $this->categoryCache[$slug] ??= FabricCategory::query()->firstOrCreate(
198	            ['slug' => $slug],
199	            ['name' => ['it' => Str::headline($slug), 'en' => Str::headline($slug)]],
200	        );
201	    }
202	
203	    private function normalize(string $value): string
204	    {
205	        return trim((string) preg_replace('/\s+/', ' ', mb_strtolower($value)));
206	    }
207	
208	    private function s(mixed $value): string
209	    {
210	        return is_scalar($value) ? trim((string) $value) : '';
211	    }
212	
213	    private function sOrNull(mixed $value): ?string
214	    {
215	        $s = $this->s($value);
216	
217	        return $s !== '' ? $s : null;
218	    }
219	}
